import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useLoaderData, useNavigate, useRevalidator } from "react-router";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";
import { getShopSubscription } from "../billing.server";
import { PLAN_LIMITS } from "../plans";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Banner,
  InlineGrid,
  Icon,
  ProgressBar,
  Box,
  Tooltip,
} from "@shopify/polaris";
import {
  SettingsIcon,
  PlusIcon,
  CodeIcon,
  ListBulletedIcon,
  EmailNewsletterIcon,
  LocationIcon,
  ExternalIcon,
  ChevronRightIcon,
} from "@shopify/polaris-icons";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const zipCodes = await db.zipCode.findMany({ where: { shop } });
  const [deliveryRulesCount, waitlistCount, subscription] = await Promise.all([
    db.deliveryRule.count({ where: { shop } }),
    db.waitlistEntry.count({ where: { shop } }),
    getShopSubscription(shop),
  ]);

  const stats = {
    total: zipCodes.length,
    allowed: zipCodes.filter((z) => z.type === "allowed").length,
    blocked: zipCodes.filter((z) => z.type === "blocked").length,
    active: zipCodes.filter((z) => z.isActive).length,
    withEta: zipCodes.filter((z) => z.eta).length,
    zones: [...new Set(zipCodes.map((z) => z.zone).filter(Boolean))].length,
    deliveryRules: deliveryRulesCount,
    waitlist: waitlistCount,
  };

  // Detect whether the App Embed is enabled in the active theme
  let appEmbedEnabled = false;
  let activeThemeName: string | null = null;
  let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
  let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;

  try {
    const themesRes = await fetch(
      `https://${shop}/admin/api/2026-01/themes.json?role=main`,
      { headers: { "X-Shopify-Access-Token": session.accessToken ?? "" } },
    );
    if (themesRes.ok) {
      const themesJson = (await themesRes.json()) as {
        themes?: { id: number; name: string }[];
      };
      const mainTheme = themesJson.themes?.[0];
      if (mainTheme) {
        const numericId = String(mainTheme.id);
        activeThemeName = mainTheme.name;
        themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
        themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;

        const assetRes = await fetch(
          `https://${shop}/admin/api/2026-01/themes/${numericId}/assets.json?asset%5Bkey%5D=config%2Fsettings_data.json`,
          { headers: { "X-Shopify-Access-Token": session.accessToken ?? "" } },
        );
        if (assetRes.ok) {
          const assetJson = (await assetRes.json()) as {
            asset?: { value?: string };
          };
          const content = assetJson?.asset?.value;
          if (content) {
            const settingsData = JSON.parse(content) as {
              current?: { blocks?: Record<string, unknown> };
            };
            const blocks = settingsData?.current?.blocks ?? {};
            appEmbedEnabled = Object.values(blocks).some((block) => {
              const b = block as { type?: string; disabled?: boolean };
              return (
                typeof b.type === "string" &&
                (b.type.includes("app-embed") || b.type.includes("app_embed")) &&
                b.disabled !== true
              );
            });
          }
        }
      }
    }
  } catch {
    // Non-fatal — embed status defaults to false
  }

  return {
    stats,
    subscription,
    appEmbedEnabled,
    activeThemeName,
    themeEditorUrl,
    themeEditorAppEmbedsUrl,
  };
};

export default function DashboardPage() {
  const { stats, subscription, appEmbedEnabled, activeThemeName, themeEditorUrl, themeEditorAppEmbedsUrl } = useLoaderData<typeof loader>();
  const navigate = useNavigate();
  const { revalidate, state: revalidateState } = useRevalidator();
  const limits = PLAN_LIMITS[subscription.planTier];
  const isFreePlan = subscription.planTier === "free";
  const isEmpty = stats.total === 0;

  const usagePercent =
    limits.maxZipCodes !== Infinity
      ? Math.min(100, Math.round((stats.total / limits.maxZipCodes) * 100))
      : 0;

  const planLabel =
    subscription.planTier === "ultimate"
      ? "Ultimate"
      : subscription.planTier === "pro"
        ? "Pro"
        : "Free";

  return (
    <Page
      title="Dashboard"
      subtitle={`${planLabel} Plan`}
      primaryAction={{
        content: "Add Zip Code",
        icon: PlusIcon,
        onAction: () => navigate("/app/zip-codes"),
      }}
    >
      <Box paddingBlockEnd="1600">
        <Layout>

          {/* 1. App Status card — always visible */}
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <InlineStack align="space-between" blockAlign="center">
                  <BlockStack gap="100">
                    <Text as="h2" variant="headingMd">App Status</Text>
                    {activeThemeName && (
                      <Text as="p" variant="bodySm" tone="subdued">
                        Active theme: {activeThemeName}
                      </Text>
                    )}
                  </BlockStack>
                  <InlineStack gap="300" blockAlign="center">
                    <Badge tone={appEmbedEnabled ? "success" : "warning"}>
                      {appEmbedEnabled ? "Active" : "Not Active"}
                    </Badge>
                    <Button
                      variant="tertiary"
                      size="slim"
                      loading={revalidateState === "loading"}
                      onClick={revalidate}
                    >
                      Refresh
                    </Button>
                  </InlineStack>
                </InlineStack>

                {appEmbedEnabled ? (
                  <Button
                    variant="plain"
                    icon={ExternalIcon}
                    url={themeEditorUrl}
                    target="_blank"
                  >
                    Open Theme Editor
                  </Button>
                ) : (
                  <BlockStack gap="300">
                    <Banner tone="warning">
                      <Text as="p" variant="bodySm">
                        The app is not active on your storefront. Complete the two steps below, then click <strong>Refresh</strong>.
                      </Text>
                    </Banner>
                    <BlockStack gap="300">
                      <InlineStack gap="300" blockAlign="center">
                        <Box
                          background="bg-surface-secondary"
                          borderRadius="full"
                          padding="150"
                          width="28px"
                        >
                          <Text as="p" variant="bodySm" fontWeight="bold" alignment="center">
                            1
                          </Text>
                        </Box>
                        <BlockStack gap="050">
                          <Text as="p" variant="bodyMd" fontWeight="semibold">Enable App Embed</Text>
                          <Text as="p" variant="bodySm" tone="subdued">
                            In Theme Editor → App Embeds → toggle on Zip Code Checker
                          </Text>
                        </BlockStack>
                        <Button
                          variant="plain"
                          icon={ExternalIcon}
                          url={themeEditorAppEmbedsUrl}
                          target="_blank"
                        >
                          Open
                        </Button>
                      </InlineStack>

                      <InlineStack gap="300" blockAlign="center">
                        <Box
                          background="bg-surface-secondary"
                          borderRadius="full"
                          padding="150"
                          width="28px"
                        >
                          <Text as="p" variant="bodySm" fontWeight="bold" alignment="center">
                            2
                          </Text>
                        </Box>
                        <BlockStack gap="050">
                          <Text as="p" variant="bodyMd" fontWeight="semibold">Add Widget to Pages</Text>
                          <Text as="p" variant="bodySm" tone="subdued">
                            Product template → Add block → Zip Code Checker → Save
                          </Text>
                        </BlockStack>
                        <Button
                          variant="plain"
                          icon={ExternalIcon}
                          url={`${themeEditorUrl}?template=product`}
                          target="_blank"
                        >
                          Open
                        </Button>
                      </InlineStack>
                    </BlockStack>
                  </BlockStack>
                )}
              </BlockStack>
            </Card>
          </Layout.Section>

          {/* 2. Stats card — only when not empty */}
          {!isEmpty && (
            <Layout.Section>
              <Card>
                <InlineGrid columns={{ xs: 2, sm: 3, md: 5 }} gap="600">
                  {/* Zip Codes — primary metric */}
                  <BlockStack gap="100">
                    <Text as="p" variant="heading2xl" fontWeight="bold">
                      {stats.total}
                      {limits.maxZipCodes !== Infinity && (
                        <Text as="span" variant="bodyMd" tone="subdued" fontWeight="regular">
                          {" "}/ {limits.maxZipCodes}
                        </Text>
                      )}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Zip codes
                    </Text>
                  </BlockStack>

                  {/* Allowed */}
                  <BlockStack gap="100">
                    <Text as="p" variant="heading2xl" fontWeight="bold" tone="success">
                      {stats.allowed}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Allowed zones
                    </Text>
                  </BlockStack>

                  {/* Blocked — tooltip on free plan */}
                  <BlockStack gap="100">
                    <Text
                      as="p"
                      variant="heading2xl"
                      fontWeight="bold"
                      tone={isFreePlan ? "subdued" : stats.blocked > 0 ? "critical" : undefined}
                    >
                      {stats.blocked}
                    </Text>
                    <Tooltip content="Available on Pro plan">
                      <Text as="p" variant="bodySm" tone="subdued">
                        Blocked zones {isFreePlan ? "🔒" : ""}
                      </Text>
                    </Tooltip>
                  </BlockStack>

                  {/* Waitlist */}
                  <BlockStack gap="100">
                    <Text
                      as="p"
                      variant="heading2xl"
                      fontWeight="bold"
                      tone={stats.waitlist > 0 ? "caution" : undefined}
                    >
                      {stats.waitlist}
                    </Text>
                    <BlockStack gap="050">
                      <Text as="p" variant="bodySm" tone="subdued">
                        On waitlist
                      </Text>
                      {stats.waitlist > 0 && (
                        <Badge tone="attention">New</Badge>
                      )}
                    </BlockStack>
                  </BlockStack>

                  {/* Delivery Rules */}
                  <BlockStack gap="100">
                    <Text as="p" variant="heading2xl" fontWeight="bold">
                      {stats.deliveryRules}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Delivery rules
                    </Text>
                  </BlockStack>
                </InlineGrid>
              </Card>
            </Layout.Section>
          )}

          {/* 3. Usage bar — slim Banner, only on free plan with data and finite limit */}
          {isFreePlan && !isEmpty && limits.maxZipCodes !== Infinity && (
            <Layout.Section>
              <Banner tone={usagePercent >= 80 ? "warning" : "info"}>
                <BlockStack gap="200">
                  <Text as="p" variant="bodySm">
                    {stats.total} of {limits.maxZipCodes} zip codes used
                  </Text>
                  <ProgressBar
                    progress={usagePercent}
                    tone={usagePercent >= 80 ? "critical" : "highlight"}
                    size="small"
                  />
                </BlockStack>
              </Banner>
            </Layout.Section>
          )}

          {/* 4. Upgrade banner — only when on free plan with data and at 60%+ usage */}
          {isFreePlan && !isEmpty && usagePercent >= 60 && (
            <Layout.Section>
              <Banner
                title="Unlock unlimited zip codes & blocked zones"
                tone="info"
                action={{
                  content: "Upgrade to Pro",
                  onAction: () => navigate("/app/pricing"),
                }}
              >
                <Text as="p" variant="bodyMd">
                  You&apos;ve used {stats.total} of {limits.maxZipCodes} zip codes. Upgrade to Pro for unlimited zip codes, blocked zones, and delivery rules.
                </Text>
              </Banner>
            </Layout.Section>
          )}

          {/* 5. Getting Started card — only when isEmpty */}
          {isEmpty && (
            <Layout.Section>
              <Card>
                <BlockStack gap="500">
                  <Text as="h2" variant="headingMd">
                    Get started in 3 steps
                  </Text>
                  <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
                    <BlockStack gap="150" inlineAlign="start">
                      <Box
                        background="bg-fill-brand"
                        borderRadius="full"
                        padding="150"
                        width="32px"
                      >
                        <Text as="p" variant="bodySm" fontWeight="bold" alignment="center" tone="text-inverse">
                          1
                        </Text>
                      </Box>
                      <Text as="h3" variant="headingSm">
                        Add your zip codes
                      </Text>
                      <Text as="p" variant="bodySm" tone="subdued">
                        Add delivery areas one by one or import via CSV.
                      </Text>
                      <Button variant="primary" size="slim" onClick={() => navigate("/app/zip-codes")}>
                        Add Zip Codes
                      </Button>
                    </BlockStack>

                    <BlockStack gap="150" inlineAlign="start">
                      <Box
                        background="bg-fill-brand"
                        borderRadius="full"
                        padding="150"
                        width="32px"
                      >
                        <Text as="p" variant="bodySm" fontWeight="bold" alignment="center" tone="text-inverse">
                          2
                        </Text>
                      </Box>
                      <Text as="h3" variant="headingSm">
                        Customise your widget
                      </Text>
                      <Text as="p" variant="bodySm" tone="subdued">
                        Match the widget to your store&apos;s branding.
                      </Text>
                      <Button size="slim" onClick={() => navigate("/app/widget")}>
                        Customise Widget
                      </Button>
                    </BlockStack>

                    <BlockStack gap="150" inlineAlign="start">
                      <Box
                        background="bg-fill-brand"
                        borderRadius="full"
                        padding="150"
                        width="32px"
                      >
                        <Text as="p" variant="bodySm" fontWeight="bold" alignment="center" tone="text-inverse">
                          3
                        </Text>
                      </Box>
                      <Text as="h3" variant="headingSm">
                        Set delivery rules
                      </Text>
                      <Text as="p" variant="bodySm" tone="subdued">
                        Configure fees, cutoff times, and schedules per zone.
                      </Text>
                      <Button size="slim" onClick={() => navigate("/app/delivery-rules")}>
                        Set Rules
                      </Button>
                    </BlockStack>
                  </InlineGrid>
                </BlockStack>
              </Card>
            </Layout.Section>
          )}

          {/* 6. Quick Actions — full-width ZIP codes card + 2x2 grid */}
          <Layout.Section>
            <BlockStack gap="300">
              <Text as="h2" variant="headingMd">
                Quick Actions
              </Text>

              {/* ZIP Codes — full-width primary card */}
              <Box
                onClick={() => navigate("/app/zip-codes")}
                style={{ cursor: "pointer" }}
              >
                <Card>
                  <Box background="bg-surface-highlight" borderRadius="200" padding="400">
                    <InlineStack align="space-between" blockAlign="center">
                      <InlineStack gap="400" blockAlign="center">
                        <Box
                          background="bg-surface-secondary"
                          borderRadius="200"
                          padding="300"
                          width="fit-content"
                        >
                          <Icon source={LocationIcon} tone="base" />
                        </Box>
                        <BlockStack gap="050">
                          <Text as="h3" variant="headingSm">
                            Manage Zip Codes
                          </Text>
                          <Text as="p" variant="bodySm" tone="subdued">
                            {stats.total} zip codes · {stats.allowed} allowed
                          </Text>
                        </BlockStack>
                      </InlineStack>
                      <Icon source={ChevronRightIcon} tone="subdued" />
                    </InlineStack>
                  </Box>
                </Card>
              </Box>

              {/* Remaining 4 cards — 2x2 grid */}
              <InlineGrid columns={{ xs: 1, sm: 2, md: 2 }} gap="400">

                <Box
                  onClick={() => navigate("/app/delivery-rules")}
                  style={{ cursor: "pointer" }}
                >
                  <Card>
                    <BlockStack gap="300">
                      <InlineStack align="space-between" blockAlign="center">
                        <Box
                          background="bg-surface-secondary"
                          borderRadius="200"
                          padding="300"
                          width="fit-content"
                        >
                          <Icon source={ListBulletedIcon} tone="base" />
                        </Box>
                        <Icon source={ChevronRightIcon} tone="subdued" />
                      </InlineStack>
                      <BlockStack gap="050">
                        <Text as="h3" variant="headingSm">
                          Delivery Rules
                        </Text>
                        <Text as="p" variant="bodySm" tone="subdued">
                          Set fees, cutoff times, and zone-based schedules.
                        </Text>
                        {stats.deliveryRules > 0 && (
                          <Text as="p" variant="bodySm" tone="subdued">
                            {stats.deliveryRules} rules
                          </Text>
                        )}
                      </BlockStack>
                    </BlockStack>
                  </Card>
                </Box>

                <Box
                  onClick={() => navigate("/app/widget")}
                  style={{ cursor: "pointer" }}
                >
                  <Card>
                    <BlockStack gap="300">
                      <InlineStack align="space-between" blockAlign="center">
                        <Box
                          background="bg-surface-secondary"
                          borderRadius="200"
                          padding="300"
                          width="fit-content"
                        >
                          <Icon source={CodeIcon} tone="base" />
                        </Box>
                        <Icon source={ChevronRightIcon} tone="subdued" />
                      </InlineStack>
                      <BlockStack gap="050">
                        <Text as="h3" variant="headingSm">
                          Widget Customisation
                        </Text>
                        <Text as="p" variant="bodySm" tone="subdued">
                          Style the storefront widget to match your store.
                        </Text>
                      </BlockStack>
                    </BlockStack>
                  </Card>
                </Box>

                <Box
                  onClick={() => navigate("/app/waitlist")}
                  style={{ cursor: "pointer" }}
                >
                  <Card>
                    <BlockStack gap="300">
                      <InlineStack align="space-between" blockAlign="center">
                        <Box
                          background="bg-surface-secondary"
                          borderRadius="200"
                          padding="300"
                          width="fit-content"
                        >
                          <Icon source={EmailNewsletterIcon} tone="base" />
                        </Box>
                        <Icon source={ChevronRightIcon} tone="subdued" />
                      </InlineStack>
                      <BlockStack gap="050">
                        <Text as="h3" variant="headingSm">
                          Customer Waitlist
                        </Text>
                        <Text as="p" variant="bodySm" tone="subdued">
                          Customers waiting for delivery to their zip code.
                        </Text>
                        {stats.waitlist > 0 && (
                          <Text as="p" variant="bodySm" tone="subdued">
                            {stats.waitlist} waiting
                          </Text>
                        )}
                      </BlockStack>
                    </BlockStack>
                  </Card>
                </Box>

                <Box
                  onClick={() => navigate("/app/settings")}
                  style={{ cursor: "pointer" }}
                >
                  <Card>
                    <BlockStack gap="300">
                      <InlineStack align="space-between" blockAlign="center">
                        <Box
                          background="bg-surface-secondary"
                          borderRadius="200"
                          padding="300"
                          width="fit-content"
                        >
                          <Icon source={SettingsIcon} tone="base" />
                        </Box>
                        <Icon source={ChevronRightIcon} tone="subdued" />
                      </InlineStack>
                      <BlockStack gap="050">
                        <Text as="h3" variant="headingSm">
                          Settings
                        </Text>
                        <Text as="p" variant="bodySm" tone="subdued">
                          Manage your subscription plan and app settings.
                        </Text>
                      </BlockStack>
                    </BlockStack>
                  </Card>
                </Box>

              </InlineGrid>
            </BlockStack>
          </Layout.Section>

        </Layout>
      </Box>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

